            print(paste("...Independent est. = ",round(mean(var1,na.rm=TRUE),digits=3),sep=""))
            print(paste("...Analysis est.    = ",round(mean(var3,na.rm=TRUE),digits=3),sep=""))            
            # Determine the y-axis range
