    }
    zrange4 = quantile(values(var4), prob=c(0.10,0.90), na.rm=TRUE)
    var4[var4 < zrange4[1]] = zrange4[1] ; var4[var4 > zrange4[2]] = zrange4[2]                
    if (zrange4[1] < 0 & zrange4[2] > 0) {
