             if (create_plot) {
                 plot(cluster_var[c,]~x_axis, type="l", lwd=2, col = c_colours[c], main=expression(paste("GPP (MgC h",a^-1,y^-1,")",sep="")), 
                      xlab="", cex.main=1.3, cex.axis=1.2, ylab="", ylim=c(0,ymax))
                 create_plot = FALSE
