    # legend position
    ee = ext(var1) ; e = rep(NA, 4)
    e[1] = ee[2] + (abs(diff(ee[1:2]))* 0.027) ; e[2] = e[1] + (abs(diff(ee[1:2]))* 0.027)
    e[3] = ee[3] ; e[4] = ee[4]
