    dom_sinkC = which(var3 > 0 & grid_output$final_dCdom_gCm2[,,ci95[1]] > 0)
    dom_sourceC = which(var3 < 0 & grid_output$final_dCdom_gCm2[,,ci95[2]] < 0)
