    var3 = rast(vals = t((var3)[,dim(PROJECT$area_m2)[2]:1]), ext = ext(cardamom_ext), crs = crs(cardamom_ext), res=res(cardamom_ext))
    # legend position
    ee = ext(var1) ; e = rep(NA, 4)
    e[1] = ee[2] + (abs(diff(ee[1:2]))* 0.027) ; e[2] = e[1] + (abs(diff(ee[1:2]))* 0.027)
    e[3] = ee[3] ; e[4] = ee[4]
    # ranges
