    var2 = grid_output$SS_foliage_gCm2[,,mid_quant]-grid_output$mean_foliage_gCm2[,,mid_quant]
    var3 = grid_output$SS_roots_gCm2[,,mid_quant]-grid_output$mean_roots_gCm2[,,mid_quant]
