        dev.off()
                
        # Extract the proportions         
        var1 = grid_output$NaturalFractionOfTurnover_wood[,,mid_quant]
        var2 = grid_output$FireFractionOfTurnover_wood[,,mid_quant]
        var3 = grid_output$HarvestFractionOfTurnover_wood[,,mid_quant]
